            if (command[i] == 'G') {
                res += 'G';
                i += 1;
            } else if (command[i + 1] == ')') {
                res += 'o';
                i += 2;
            } else {
                res += "al";
                i += 4;
            }
        }
        return res;
    }
};

c.java:
class Solution {
    public String interpret(String command) {
        StringBuilder res = new StringBuilder();
        int i = 0;
        while (i < command.length()) {
            char c = command.charAt(i);
            if (c == 'G') {
                res.append('G');
                i += 1;
            } else if (command.charAt(i + 1) == ')') {
                res.append('o');
                i += 2;
            } else {
                res.append("al");
                i += 4;
            }
        }
        return res.toString();
    }
}

